def ana_sayfa(uyari, banka, alici, iban):
    return f"<!DOCTYPE html><html lang='tr'><head><meta charset='UTF-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Veri Otoyolu</title><style>body{{font-family:sans-serif;background:#0f172a;color:#f8fafc;max-width:680px;margin:20px auto;padding:16px}}.kutu{{background:#1e293b;padding:20px;border-radius:12px;margin-bottom:16px;border:1px solid #334155}}input,button{{padding:12px;border-radius:8px;border:none;font-size:15px;margin-top:8px;width:100%;box-sizing:border-box}}input{{background:#0f172a;color:white;border:1px solid #475569}}button{{background:#3b82f6;color:white;font-weight:bold}}.yesil{{background:#10b981}}.mor{{background:#8b5cf6}}</style></head><body><h1>🚀 Veri Otoyolu</h1><div class='kutu'><h3>1. Ücretsiz Anahtar Al</h3>{uyari}<form method='POST' action='/kayit'><input name='ad' placeholder='Proje Adı' required><button>API Anahtarı Üret</button></form></div><div class='kutu'><h3>2. Dosya Yükle</h3><form method='POST' action='/yukle' enctype='multipart/form-data'><input name='anahtar' placeholder='vo_...' required><input type='file' name='dosya' required><button class='yesil'>Yükle</button></form></div><div class='kutu'><h3>3. Dosyamı Gör ve İndir</h3><form method='GET' action='/kontrol'><input name='anahtar' placeholder='vo_...' required><button class='mor'>📂 Dosyamı Görüntüle</button></form></div><div class='kutu'><h3>4. Otomatik Kota (100 TL = 100 Hak)</h3><p><b>{banka} - {alici}</b><br>IBAN: <code>{iban}</code><br><small>Açıklamaya sadece API anahtarınızı yazın. Ödeme algılandığında hesabınıza <b>100 Hak</b> tanımlanır.</small></p></div></body></html>"

def kokpit(rows, logs, gizli):
    tr = "".join([f"<tr><td>{ad}</td><td><code>{k}</code></td><td>{m_ip}</td><td>{kalan}</td><td>{gecis}</td><td>{(dosya or 'oyun_yama_v1.pak').replace(k+'_','')}</td><td><a href='/onizle?anahtar={k}' target='_blank' style='color:#38bdf8;margin-right:10px;'>👁️ Gör</a><a href='/yonetim?sifre={gizli}&ekle={k}' style='color:#10b981;'>+100 Hak</a></td></tr>" for k, ad, kalan, gecis, dosya, m_ip in rows])
    ltr = "".join([f"<tr><td>{z}</td><td><code>{l_ip}</code></td><td><b>{isl}</b></td><td>{det}</td></tr>" for z, l_ip, isl, det in logs])
    return f"<body style='font-family:sans-serif;background:#0f172a;color:white;padding:24px;'><h2>🎛️ Veri Otoyolu Kokpit</h2><table border='1' cellpadding='8' style='border-collapse:collapse;width:100%;border-color:#334155;'><tr><th>Proje</th><th>Anahtar</th><th>IP</th><th>Kalan</th><th>Geçiş</th><th>Dosya</th><th>İşlem</th></tr>{tr}</table><h3>📜 Son İşlem Günlüğü</h3><table border='1' cellpadding='8' style='border-collapse:collapse;width:100%;border-color:#334155;'><tr><th>Zaman</th><th>IP Adresi</th><th>İşlem</th><th>Detay</th></tr>{ltr}</table><br><a href='/' style='color:#38bdf8;'>← Ana Sayfa</a></body>"
